package com.heng.community;

import com.heng.config.BizException;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;
import java.sql.Statement;
import java.util.*;

@Service
public class SocialService {
 static java.sql.Timestamp ago(long seconds){return java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(seconds));}
 final JdbcTemplate db;
 private final JsonMapper json=JsonMapper.builder().build();
 public SocialService(JdbcTemplate db){this.db=db;}
 long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 long insert(String sql,Object...args){var holder=new GeneratedKeyHolder();db.update(c->{String pk=sql.startsWith("INSERT INTO v_friend_request")?"request_id":sql.startsWith("INSERT INTO v_conversation(")?"conversation_id":"message_id";var s=c.prepareStatement(sql,new String[]{pk});for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;},holder);return Objects.requireNonNull(holder.getKey()).longValue();}
 void active(long id){if(db.queryForObject("SELECT COUNT(*) FROM v_member WHERE member_id=? AND status=1",Long.class,id)!=1)throw new BizException("会员不存在或已停用");}
 void pair(long a,long b){if(a==b)throw new BizException("不能对自己执行此操作");for(long id:new long[]{Math.min(a,b),Math.max(a,b)}){var rows=db.queryForList("SELECT member_id FROM v_member WHERE member_id=? AND status=1 FOR UPDATE",id);if(rows.isEmpty())throw new BizException("会员不存在或已停用");}}
 boolean blocked(long a,long b){return db.queryForObject("SELECT COUNT(*) FROM v_social_block WHERE (member_id=? AND blocked_id=?) OR (member_id=? AND blocked_id=?)",Long.class,a,b,b,a)>0;}
 void friends(long a,long b){active(a);active(b);if(blocked(a,b)||db.queryForObject("SELECT COUNT(*) FROM v_friend WHERE member_id=? AND friend_id=?",Long.class,a,b)!=1)throw new BizException("请先添加好友，或解除屏蔽后继续");}
 public List<Map<String,Object>> search(long me,String q){q=q==null?"":q.trim();if(q.length()<2||q.length()>50)throw new BizException("请输入 2–50 个字符搜索账号或昵称");String like="%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%";return db.queryForList("SELECT member_id AS \"memberId\",username,nickname,avatar_url AS \"avatarUrl\" FROM v_member WHERE status=1 AND member_id<>? AND (username LIKE ? ESCAPE '!' OR nickname LIKE ? ESCAPE '!') AND NOT EXISTS(SELECT 1 FROM v_social_block b WHERE (b.member_id=? AND b.blocked_id=v_member.member_id) OR (b.blocked_id=? AND b.member_id=v_member.member_id)) ORDER BY member_id LIMIT 20",me,like,like,me,me);}
 public Map<String,Object> friendList(long me){return Map.of("friends",db.queryForList("SELECT m.member_id AS \"memberId\",m.username,m.nickname,m.avatar_url AS \"avatarUrl\",f.remark FROM v_friend f JOIN v_member m ON m.member_id=f.friend_id WHERE f.member_id=? AND m.status=1 ORDER BY m.member_id",me),"incoming",db.queryForList("SELECT r.request_id AS \"requestId\",r.sender_id AS \"memberId\",m.nickname,m.username,r.note,r.create_time AS \"createTime\" FROM v_friend_request r JOIN v_member m ON m.member_id=r.sender_id WHERE r.receiver_id=? AND r.status='PENDING' ORDER BY r.request_id DESC LIMIT 50",me),"outgoing",db.queryForList("SELECT r.request_id AS \"requestId\",r.receiver_id AS \"memberId\",m.nickname,m.username,r.status,r.create_time AS \"createTime\" FROM v_friend_request r JOIN v_member m ON m.member_id=r.receiver_id WHERE r.sender_id=? ORDER BY r.request_id DESC LIMIT 50",me),"blocked",db.queryForList("SELECT m.member_id AS \"memberId\",m.nickname FROM v_social_block b JOIN v_member m ON m.member_id=b.blocked_id WHERE b.member_id=?",me));}
 @Transactional public long request(long me,long target,String note){pair(me,target);if(blocked(me,target))throw new BizException("暂时无法发送好友申请");if(db.queryForObject("SELECT COUNT(*) FROM v_friend WHERE member_id=? AND friend_id=?",Long.class,me,target)>0)throw new BizException("已经是好友");if(db.queryForObject("SELECT COUNT(*) FROM v_friend_request WHERE sender_id=? AND create_time>?",Long.class,me,ago(86400))>=30)throw new BizException("今日好友申请次数已达上限");var pending=db.queryForList("SELECT request_id FROM v_friend_request WHERE sender_id=? AND receiver_id=? AND status='PENDING'",me,target);if(!pending.isEmpty())return number(pending.get(0),"request_id");long id=insert("INSERT INTO v_friend_request(sender_id,receiver_id,note) VALUES(?,?,?)",me,target,clean(note,200,false));event(target,Map.of("type","friends"));return id;}
 @Transactional public void decide(long me,long id,boolean accept){var rows=db.queryForList("SELECT * FROM v_friend_request WHERE request_id=?",id);if(rows.isEmpty()||number(rows.get(0),"receiver_id")!=me)throw new BizException("好友申请不存在");long other=number(rows.get(0),"sender_id");pair(me,other);var row=db.queryForMap("SELECT * FROM v_friend_request WHERE request_id=? FOR UPDATE",id);if(!"PENDING".equals(row.get("status")))throw new BizException("申请已处理");if(accept){if(blocked(me,other))throw new BizException("请先解除屏蔽");db.update("INSERT INTO v_friend(member_id,friend_id) VALUES(?,?),(?,?) ON CONFLICT DO NOTHING",me,other,other,me);}db.update("UPDATE v_friend_request SET status=? WHERE request_id=?",accept?"ACCEPTED":"REJECTED",id);event(me,Map.of("type","friends"));event(other,Map.of("type","friends"));}
 @Transactional public void remove(long me,long other){pair(me,other);db.update("DELETE FROM v_friend WHERE (member_id=? AND friend_id=?) OR (member_id=? AND friend_id=?)",me,other,other,me);event(me,Map.of("type","friends"));event(other,Map.of("type","friends"));}
 @Transactional public void remark(long me,long other,String remark){if(db.update("UPDATE v_friend SET remark=? WHERE member_id=? AND friend_id=?",clean(remark,50,false),me,other)!=1)throw new BizException("好友不存在");}
 @Transactional public void block(long me,long other,boolean enabled){pair(me,other);if(enabled){db.update("INSERT INTO v_social_block(member_id,blocked_id) VALUES(?,?) ON CONFLICT DO NOTHING",me,other);db.update("DELETE FROM v_friend WHERE (member_id=? AND friend_id=?) OR (member_id=? AND friend_id=?)",me,other,other,me);db.update("UPDATE v_friend_request SET status='REJECTED' WHERE status='PENDING' AND ((sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?))",me,other,other,me);}else db.update("DELETE FROM v_social_block WHERE member_id=? AND blocked_id=?",me,other);event(me,Map.of("type","friends"));event(other,Map.of("type","friends"));}
 @Transactional public long privateChat(long me,long other){pair(me,other);friends(me,other);String key=Math.min(me,other)+":"+Math.max(me,other);var rows=db.queryForList("SELECT conversation_id FROM v_conversation WHERE private_key=?",key);if(!rows.isEmpty())return number(rows.get(0),"conversation_id");long id=insert("INSERT INTO v_conversation(kind,owner_id,private_key) VALUES('PRIVATE',?,?)",me,key);db.update("INSERT INTO v_conversation_member(conversation_id,member_id,role) VALUES(?,?,'MEMBER'),(?,?,'MEMBER')",id,me,id,other);broadcast(id,Map.of("type","conversations"));return id;}
 @Transactional public long group(long me,String name,List<Long> invited){var members=new LinkedHashSet<>(invited==null?List.<Long>of():invited);members.remove(me);if(members.isEmpty()||members.size()>49)throw new BizException("群聊需选择 1–49 位好友");db.queryForList("SELECT member_id FROM v_member WHERE member_id=? FOR UPDATE",me);for(long other:members)friends(me,other);long id=insert("INSERT INTO v_conversation(kind,name,owner_id) VALUES('GROUP',?,?)",clean(name,80,true),me);db.update("INSERT INTO v_conversation_member(conversation_id,member_id,role) VALUES(?,?,'OWNER')",id,me);for(long other:members)db.update("INSERT INTO v_conversation_member(conversation_id,member_id) VALUES(?,?)",id,other);broadcast(id,Map.of("type","conversations"));return id;}
 Map<String,Object> membership(long me,long id){var rows=db.queryForList("SELECT cm.*,c.kind,c.owner_id,c.name FROM v_conversation_member cm JOIN v_conversation c ON c.conversation_id=cm.conversation_id WHERE cm.member_id=? AND cm.conversation_id=?",me,id);if(rows.isEmpty())throw new BizException("会话不存在或无访问权限");return rows.get(0);}
 public Map<String,Object> detail(long me,long id){var membership=membership(me,id);return Map.of("conversationId",id,"kind",membership.get("kind"),"name",Objects.toString(membership.get("name"),""),"role",membership.get("role"),"members",db.queryForList("SELECT m.member_id AS \"memberId\",m.nickname,m.username,m.avatar_url AS \"avatarUrl\",cm.role FROM v_conversation_member cm JOIN v_member m ON m.member_id=cm.member_id WHERE cm.conversation_id=? ORDER BY m.member_id",id));}
 public List<Map<String,Object>> conversations(long me){return db.queryForList("SELECT c.conversation_id AS \"conversationId\",c.kind,COALESCE(c.name,(SELECT COALESCE(NULLIF(m.nickname,''),m.username) FROM v_conversation_member other JOIN v_member m ON m.member_id=other.member_id WHERE other.conversation_id=c.conversation_id AND other.member_id<>? LIMIT 1)) AS name,cm.role,(SELECT COUNT(*) FROM v_chat_message msg WHERE msg.conversation_id=c.conversation_id AND msg.message_id>GREATEST(cm.last_read_id,cm.joined_message_id) AND msg.sender_id<>?) AS \"unreadCount\",(SELECT content FROM v_chat_message msg WHERE msg.conversation_id=c.conversation_id AND msg.message_id>cm.joined_message_id ORDER BY message_id DESC LIMIT 1) AS \"lastMessage\",(SELECT MAX(message_id) FROM v_chat_message msg WHERE msg.conversation_id=c.conversation_id) AS \"lastMessageId\" FROM v_conversation c JOIN v_conversation_member cm ON cm.conversation_id=c.conversation_id WHERE cm.member_id=? ORDER BY \"lastMessageId\" DESC,c.conversation_id DESC LIMIT 100",me,me,me);}
 public List<Map<String,Object>> messages(long me,long id,long before){var row=membership(me,id);return db.queryForList("SELECT msg.message_id AS \"messageId\",msg.sender_id AS \"senderId\",msg.kind,msg.content,msg.product_id AS \"productId\",msg.media_id AS \"mediaId\",msg.create_time AS \"createTime\",m.nickname,m.username,p.name AS \"productName\",p.main_image_url AS \"productImage\",p.min_price_fen AS \"productPriceFen\" FROM v_chat_message msg JOIN v_member m ON m.member_id=msg.sender_id LEFT JOIN v_goods_spu p ON p.spu_id=msg.product_id WHERE msg.conversation_id=? AND msg.message_id>? AND (?=0 OR msg.message_id<?) ORDER BY msg.message_id DESC LIMIT 50",id,number(row,"joined_message_id"),before,before);}
 @Transactional public long send(long me,long id,String kind,String content,Long productId,String mediaId,String key){db.queryForList("SELECT member_id FROM v_member WHERE member_id=? FOR UPDATE",me);var membership=membership(me,id);db.queryForList("SELECT conversation_id FROM v_conversation WHERE conversation_id=? FOR UPDATE",id);membership=membership(me,id);if("PRIVATE".equals(membership.get("kind"))){long other=db.queryForObject("SELECT member_id FROM v_conversation_member WHERE conversation_id=? AND member_id<>?",Long.class,id,me);friends(me,other);}if(key==null||!key.matches("[A-Za-z0-9_-]{8,80}"))throw new BizException("缺少有效请求编号");var old=db.queryForList("SELECT * FROM v_chat_message WHERE sender_id=? AND request_key=?",me,key);String body=clean(content,"TEXT".equals(kind)?2000:200,false);if(kind==null||!Set.of("TEXT","PRODUCT","IMAGE").contains(kind))throw new BizException("消息类型不支持");if(!old.isEmpty()){var r=old.get(0);if(number(r,"conversation_id")!=id||!Objects.equals(r.get("kind"),kind)||!Objects.equals(r.get("content"),body)||!Objects.equals(r.get("product_id"),productId)||!Objects.equals(r.get("media_id"),mediaId))throw new BizException("请求编号已被其他消息使用");return number(r,"message_id");}if(db.queryForObject("SELECT COUNT(*) FROM v_chat_message WHERE sender_id=? AND create_time>?",Long.class,me,ago(60))>=60)throw new BizException("发送过于频繁，请稍后重试");if("TEXT".equals(kind)&&body.isBlank())throw new BizException("消息不能为空");if("PRODUCT".equals(kind)){if(productId==null||db.queryForObject("SELECT COUNT(*) FROM v_goods_spu WHERE spu_id=? AND on_sale=1 AND del_flag='0'",Long.class,productId)!=1)throw new BizException("商品不存在或已下架");}else productId=null;if("IMAGE".equals(kind)){if(mediaId==null||db.queryForObject("SELECT COUNT(*) FROM v_chat_media WHERE media_id=? AND owner_id=? AND conversation_id=?",Long.class,mediaId,me,id)!=1)throw new BizException("图片不存在或无权使用");}else mediaId=null;long message=insert("INSERT INTO v_chat_message(conversation_id,sender_id,kind,content,product_id,media_id,request_key) VALUES(?,?,?,?,?,?,?)",id,me,kind,body,productId,mediaId,key);broadcast(id,Map.of("type","message","conversationId",id,"messageId",message));return message;}
 @Transactional public void read(long me,long id,long message){membership(me,id);long max=db.queryForObject("SELECT COALESCE(MAX(message_id),0) FROM v_chat_message WHERE conversation_id=?",Long.class,id);long cursor=Math.min(max,Math.max(0,message));if(db.update("UPDATE v_conversation_member SET last_read_id=? WHERE conversation_id=? AND member_id=? AND last_read_id<?",cursor,id,me,cursor)>0)event(me,Map.of("type","read","conversationId",id));}
 @Transactional public void rename(long me,long id,String name){var row=membership(me,id);if(!"GROUP".equals(row.get("kind"))||!Set.of("OWNER","ADMIN").contains(row.get("role")))throw new BizException("仅群主或管理员可修改群名");db.update("UPDATE v_conversation SET name=? WHERE conversation_id=?",clean(name,80,true),id);broadcast(id,Map.of("type","conversations"));}
 @Transactional public void invite(long me,long id,List<Long> invited){db.queryForList("SELECT conversation_id FROM v_conversation WHERE conversation_id=? FOR UPDATE",id);var row=membership(me,id);if(!"GROUP".equals(row.get("kind"))||!Set.of("OWNER","ADMIN").contains(row.get("role")))throw new BizException("仅群主或管理员可邀请成员");var members=new LinkedHashSet<>(invited==null?List.<Long>of():invited);if(members.size()>49||db.queryForObject("SELECT COUNT(*) FROM v_conversation_member WHERE conversation_id=?",Long.class,id)+members.size()>50)throw new BizException("群聊最多 50 人");long max=db.queryForObject("SELECT COALESCE(MAX(message_id),0) FROM v_chat_message WHERE conversation_id=?",Long.class,id);for(long other:members){friends(me,other);db.update("INSERT INTO v_conversation_member(conversation_id,member_id,joined_message_id,last_read_id) VALUES(?,?,?,?) ON CONFLICT DO NOTHING",id,other,max,max);}broadcast(id,Map.of("type","conversations"));}
 @Transactional public void memberAction(long me,long id,long other,String action){db.queryForList("SELECT conversation_id FROM v_conversation WHERE conversation_id=? FOR UPDATE",id);var row=membership(me,id);var target=membership(other,id);if(!"GROUP".equals(row.get("kind")))throw new BizException("私聊不支持群管理");String role=row.get("role").toString(),targetRole=target.get("role").toString();if(action==null)throw new BizException("群管理操作无效");switch(action){case "REMOVE"->{if(me!=other&&(!Set.of("OWNER","ADMIN").contains(role)||"OWNER".equals(targetRole)||"ADMIN".equals(targetRole)&&!"OWNER".equals(role)))throw new BizException("无权移除此成员");if("OWNER".equals(targetRole))throw new BizException("请先转让群主后退出");db.update("DELETE FROM v_conversation_member WHERE conversation_id=? AND member_id=?",id,other);}case "ADMIN","MEMBER"->{if(!"OWNER".equals(role)||me==other)throw new BizException("仅群主可设置其他成员角色");db.update("UPDATE v_conversation_member SET role=? WHERE conversation_id=? AND member_id=?",action,id,other);}case "OWNER"->{if(!"OWNER".equals(role)||me==other)throw new BizException("仅群主可转让群聊");db.update("UPDATE v_conversation_member SET role='MEMBER' WHERE conversation_id=? AND member_id=?",id,me);db.update("UPDATE v_conversation_member SET role='OWNER' WHERE conversation_id=? AND member_id=?",id,other);db.update("UPDATE v_conversation SET owner_id=? WHERE conversation_id=?",other,id);}default->throw new BizException("群管理操作无效");}event(other,Map.of("type","conversations"));broadcast(id,Map.of("type","conversations"));}
 @Transactional public Map<String,Object> startCall(long me,long id,String media){var row=membership(me,id);if(!"PRIVATE".equals(row.get("kind"))||media==null||!Set.of("AUDIO","VIDEO").contains(media))throw new BizException("音视频通话仅支持双人私聊");long other=db.queryForObject("SELECT member_id FROM v_conversation_member WHERE conversation_id=? AND member_id<>?",Long.class,id,me);pair(me,other);friends(me,other);if(db.queryForObject("SELECT COUNT(*) FROM v_social_call WHERE state IN ('RINGING','ACCEPTED') AND update_time>? AND (caller_id IN (?,?) OR receiver_id IN (?,?))",Long.class,ago(90),me,other,me,other)>0)throw new BizException("对方或您正在通话");String call=UUID.randomUUID().toString().replace("-","");db.update("INSERT INTO v_social_call(call_id,conversation_id,caller_id,receiver_id,media,state) VALUES(?,?,?,?,?,'RINGING')",call,id,me,other,media);var result=callInfo(call);event(other,Map.of("type","call","action","RINGING","call",result));return result;}
 public Map<String,Object> callInfo(String call){return db.queryForMap("SELECT c.call_id AS \"callId\",c.conversation_id AS \"conversationId\",c.caller_id AS \"callerId\",c.receiver_id AS \"receiverId\",c.media,c.state,m.nickname AS \"callerName\" FROM v_social_call c JOIN v_member m ON m.member_id=c.caller_id WHERE call_id=?",call);}
 @Transactional public void callAction(long me,String call,String action,Object signal){var rows=db.queryForList("SELECT * FROM v_social_call WHERE call_id=? FOR UPDATE",call);if(rows.isEmpty())throw new BizException("通话不存在");var row=rows.get(0);long caller=number(row,"caller_id"),receiver=number(row,"receiver_id");if(me!=caller&&me!=receiver)throw new BizException("无通话权限");membership(me,number(row,"conversation_id"));String state=row.get("state").toString();long other=me==caller?receiver:caller;
 if(action==null)throw new BizException("通话操作无效");switch(action){case "ACCEPT"->{if(me!=receiver||!"RINGING".equals(state))throw new BizException("无法接听当前通话");friends(me,other);db.update("UPDATE v_social_call SET state='ACCEPTED',update_time=NOW() WHERE call_id=?",call);event(other,Map.of("type","call","action","ACCEPTED","call",callInfo(call)));}case "REJECT","END"->{if(!Set.of("RINGING","ACCEPTED").contains(state))return;if("REJECT".equals(action)&&me!=receiver)throw new BizException("无法拒绝此通话");db.update("UPDATE v_social_call SET state='ENDED' WHERE call_id=?",call);event(other,Map.of("type","call","action","ENDED","callId",call));}case "PING"->{if(!"ACCEPTED".equals(state))throw new BizException("通话已结束");db.update("UPDATE v_social_call SET update_time=NOW() WHERE call_id=?",call);}case "OFFER","ANSWER","ICE"->{if(!"ACCEPTED".equals(state))throw new BizException("通话未接听或已结束");friends(me,other);String encoded=json.writeValueAsString(signal);if(signal==null||encoded.length()>40000)throw new BizException("通话信令无效");if(action.equals("OFFER")&&me!=caller||action.equals("ANSWER")&&me!=receiver)throw new BizException("通话信令方向无效");db.update("UPDATE v_social_call SET update_time=NOW() WHERE call_id=?",call);event(other,Map.of("type","signal","action",action,"callId",call,"signal",signal));}default->throw new BizException("通话操作无效");}}
 public List<Map<String,Object>> activeCalls(long me){return db.queryForList("SELECT c.call_id AS \"callId\",c.conversation_id AS \"conversationId\",c.caller_id AS \"callerId\",c.receiver_id AS \"receiverId\",c.media,c.state,m.nickname AS \"callerName\" FROM v_social_call c JOIN v_member m ON m.member_id=c.caller_id WHERE c.state IN ('RINGING','ACCEPTED') AND c.update_time>? AND (c.caller_id=? OR c.receiver_id=?)",ago(90),me,me);}
 @Transactional public void expireCalls(){var rows=db.queryForList("SELECT * FROM v_social_call WHERE (state='RINGING' AND create_time<?) OR (state='ACCEPTED' AND update_time<?) FOR UPDATE",ago(60),ago(90));for(var row:rows){db.update("UPDATE v_social_call SET state='ENDED' WHERE call_id=?",row.get("call_id"));for(String k:List.of("caller_id","receiver_id"))event(number(row,k),Map.of("type","call","action","ENDED","callId",row.get("call_id")));}}
 void event(long member,Map<String,Object> value){db.update("INSERT INTO v_social_event(member_id,payload) VALUES(?,?)",member,json.writeValueAsString(value));}
 void broadcast(long id,Map<String,Object> value){for(long member:db.queryForList("SELECT member_id FROM v_conversation_member WHERE conversation_id=?",Long.class,id))event(member,value);}
 String clean(String value,int max,boolean required){String s=value==null?"":value.trim();if(s.length()>max||required&&s.isBlank())throw new BizException("内容为空或超过长度限制");return s;}
}
